mapper.select:
SELECT COUNT(*)
FROM repository
WHERE memberId = #{memberId}
  AND `name` = #{name}
  AND delStatus = 0

mapper.update:
UPDATE repository
SET name = #{name}
WHERE id = #{id}

mapper.select:
SELECT id
FROM repository
WHERE memberId = #{memberId}
  AND githubName = #{githubName}
  AND delStatus = 0

mapper.update:
UPDATE repository
SET delStatus = 1,
    delDate = NOW()
WHERE id = #{id}
  AND memberId = #{loginedMemberId}
